// Copies docs/privacy/PRIVACY.md into the AI server so /privacy serves exactly the text the app shows.
// Run after editing the notice: node tools/gen-privacy.mjs (a test fails if they drift apart).
import { readFileSync, writeFileSync } from "node:fs";
const md = readFileSync(new URL("../docs/privacy/PRIVACY.md", import.meta.url), "utf8");
writeFileSync(new URL("../worker/src/privacy-text.js", import.meta.url),
  "// Generated by tools/gen-privacy.mjs from docs/privacy/PRIVACY.md. Do not edit.\nexport default " + JSON.stringify(md) + ";\n");
console.log("privacy-text.js updated");
